package com.codeguardian.service; import com.codeguardian.entity.KnowledgeFile; import com.codeguardian.repository.KnowledgeFileRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.nio.file.*; @Service @RequiredArgsConstructor public class DocumentKnowledgeService{private final KnowledgeFileRepository files;private final Path root=Path.of("uploads","knowledge");public KnowledgeFile upload(MultipartFile f){try{Files.createDirectories(root);String safe=System.currentTimeMillis()+"-"+Path.of(f.getOriginalFilename()==null?"document":f.getOriginalFilename()).getFileName();Path target=root.resolve(safe);Files.copy(f.getInputStream(),target,StandardCopyOption.REPLACE_EXISTING);return files.save(KnowledgeFile.builder().filename(f.getOriginalFilename()).contentType(f.getContentType()).size(f.getSize()).storagePath(target.toAbsolutePath().toString()).build());}catch(IOException e){throw new IllegalStateException("Document upload failed",e);}}public Path path(Long id){return Path.of(files.findById(id).orElseThrow(()->new IllegalArgumentException("Document not found")).getStoragePath());}public void delete(Long id){var f=files.findById(id).orElseThrow(()->new IllegalArgumentException("Document not found"));try{Files.deleteIfExists(Path.of(f.getStoragePath()));}catch(IOException e){throw new IllegalStateException(e);}files.delete(f);}}
